def isMonotonic(A):
    if len(A) <= 2:
        return True
    increasing = decreasing = True
    for i in range(1, len(A)):
        if A[i] > A[i - 1]:
            decreasing = False
        elif A[i] < A[i - 1]:
            increasing = False
        if not increasing and not decreasing:
            return False
    return True
```
